import json,random
t=open('/tmp/target370.txt').read()
# build pair map
pairs={}
st=[]
for i,c in enumerate(t):
    if c=='(': st.append(i)
    elif c==')': j=st.pop(); pairs[j]=i; pairs[i]=j

def make_seed(allocator):
    seq=['A']*len(t)
    done=set()
    for i,c in enumerate(t):
        if i in pairs and i not in done:
            j=pairs[i]
            a,b=allocator(i,j)
            seq[i]=a; seq[j]=b
            done.add(i); done.add(j)
    return ''.join(seq)

# Variant 1: alternating GC/CG by stem index
def alloc_alt():
    state=[0]
    def f(i,j):
        state[0]+=1
        return ('G','C') if state[0]%2 else ('C','G')
    return f
seeds={}
seeds['alt']=make_seed.alloc_alt if False else make_seed(lambda i,j: ('G','C') if ((i+j)%2==0) else ('C','G'))

# Variant 2: G-C everywhere
seeds['gc']=make_seed(lambda i,j:('G','C'))
# Variant 3: pure C-G 
seeds['cg']=make_seed(lambda i,j:('C','G'))
# Variant 4: random G/C per pair
random.seed(1)
seeds['rand']=make_seed(lambda i,j: random.choice([('G','C'),('C','G')]))
# Variant 5: loops = U (weaker), stems GC
def make_seed_U(allocator):
    seq=['U']*len(t)
    done=set()
    for i,c in enumerate(t):
        if i in pairs and i not in done:
            j=pairs[i]
            a,b=allocator(i,j)
            seq[i]=a; seq[j]=b
            done.add(i); done.add(j)
    return ''.join(seq)
seeds['gcU']=make_seed_U(lambda i,j:('G','C'))

out=[]
for name,s in seeds.items():
    out.append(s)
    print(name,len(s))
json.dump(out, open('/tmp/seeds.json','w'))
